"""specs_s200035.py - Sonnet-w2 family L (generated by mkfamL.py). 0x41e290 returns a heap object or 0; CTOR and GUARD record the SEH chain; the guard global is zero about half the time.
Fake outer SEH records 0-2; fs:[0] compared; the new object (vtable word, stored c_in) is compared through the heap."""
from pilot import S
from recruits_util import rnd, clear_hooks, hook_rec, seh_record, seh_chain


def _mk(ctor, glob, guard):
    def gen(c):
        clear_hooks(c)
        seh_chain(c, c.rng.choice([0, 1, 2]))
        r = c.rng
        p = r.choice([0, rnd(c, 0x40), rnd(c, 0x40), rnd(c, 0x40)])
        hook_rec(c, 0x41e290, 1, ret=p, pop=0, side=seh_record(c, 2))
        hook_rec(c, ctor, 1, ret=r.getrandbits(32), pop=4, this=True, side=seh_record(c, 2))
        hook_rec(c, guard, 0, ret=r.getrandbits(32), this=True, side=seh_record(c, 2))
        c.emu.w32(glob, r.choice([0, 0, 1, r.getrandbits(32)]))
        return [r.getrandbits(32)]
    return gen


S(0x51a810, 'GUESS famL 0x51a810', 'thiscall', None, ret='eax', gen=_mk(0x500990, 0x701660, 0x51a700), note='batch200035')
S(0x51ff80, 'GUESS famL 0x51ff80', 'thiscall', None, ret='eax', gen=_mk(0x51afb0, 0x7019a8, 0x51fe70), note='batch200035')
S(0x55ec70, 'GUESS famL 0x55ec70', 'thiscall', None, ret='eax', gen=_mk(0x5062f0, 0x713f10, 0x55ea50), note='batch200035')
S(0x509630, 'GUESS famL 0x509630', 'thiscall', None, ret='eax', gen=_mk(0x5047c0, 0x701048, 0x509430), note='batch200035')
S(0x55fa40, 'GUESS famL 0x55fa40', 'thiscall', None, ret='eax', gen=_mk(0x5047c0, 0x7140c8, 0x55f870), note='batch200035')
